#include <iostream>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    int rest = n;
    int levels = 0;
    while (rest > 1) {
        rest = (rest + 1) / 2;
        levels = levels + 1;
    }

    cout << "{greet}" << endl;
    cout << "要砍 " << levels << " 次" << endl;
    return 0;
}
